	private static function accordion($node,$post_id,$arch,$cfg){$p=(array)($node['props']??array());$slots=(array)($cfg['slots']['items']??array());$wid=self::safe_id($node['id']??'accordion');$tag=in_array($p['titleTag']??'',array('div','h2','h3','h4','h5','h6'),true)?$p['titleTag']:'h3';$pos='start'===($p['iconPosition']??'')?'start':'end';$expand=sanitize_key((string)($p['expandIcon']??'plus-alt2'))?:'plus-alt2';$collapse=sanitize_key((string)($p['collapseIcon']??'minus'))?:'minus';$html='';foreach((array)($p['items']??array()) as $i=>$item){$bid=$wid.'-trigger-'.$i;$pid=$wid.'-panel-'.$i;$open=!empty($item['open']);$content=wp_kses_post((string)($item['content']??''));$cid=absint($slots[(string)$i]??$slots[$i]??0);if($cid){$component=self::component($cid,$post_id,$arch);if(''!==$component)$content=$component;}$icon='<span class="cresco-accordion__icon" aria-hidden="true" data-expand-icon="'.esc_attr($expand).'" data-collapse-icon="'.esc_attr($collapse).'"><span class="dashicons dashicons-'.esc_attr($open?$collapse:$expand).'"></span></span>';$title='<span class="cresco-accordion__title">'.esc_html((string)($item['title']??'')).'</span>';$trigger='start'===$pos?$icon.$title:$title.$icon;$html.='<div class="cresco-accordion__item"><'.$tag.' class="cresco-accordion__heading"><button type="button" id="'.esc_attr($bid).'" class="cresco-accordion__trigger" aria-expanded="'.($open?'true':'false').'" aria-controls="'.esc_attr($pid).'">'.$trigger.'</button></'.$tag.'><div id="'.esc_attr($pid).'" class="cresco-accordion__panel" role="region" aria-labelledby="'.esc_attr($bid).'"'.($open?'':' hidden').'>'.$content.'</div></div>';}return '<div'.self::attrs($node).' data-cresco-accordion data-allow-multi="'.(!empty($p['allowMulti'])?'1':'0').'" data-icon-position="'.esc_attr($pos).'">'.$html.'</div>';}
	private static function loop_template($node,$arch,$cfg){$p=(array)($node['props']??array());$q=array_merge(array('postType'=>$p['postType']??'post','postsPerPage'=>$p['perPage']??6,'order'=>$p['order']??'DESC','orderby'=>$p['orderBy']??'date','taxonomy'=>$p['taxonomy']??'','term'=>$p['term']??''),(array)($cfg['query']??array()));$param=DynamicData::sanitize_page_param($q['pageParam']??'cc_page');$paged=!empty($q['pagination'])&&isset($_GET[$param])?absint(wp_unslash($_GET[$param])):1; // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Read-only pagination.
